     <script>
       const quizQuestions = [
         {
           id: "question-1",
           legend: "1. Which of these are commonly used for systems programming?",
           helpText: "Select every answer that fits. More than one option is correct.",
           options: [
             { value: "c", title: "C", copy: "A foundational systems language used for operating systems and low-level tooling." },
             { value: "rust", title: "Rust", copy: "A modern systems language focused on memory safety and performance." },
             { value: "html", title: "HTML", copy: "A markup language for structuring web content, not a systems programming language." },
             { value: "sql", title: "SQL", copy: "A query language for relational databases rather than systems programming." }
           ],
           correctAnswers: ["c", "rust"]
         },
         {
           id: "question-2",
           legend: "2. Which languages are primarily used to run in web browsers?",
           options: [
             { value: "javascript", title: "JavaScript", copy: "The standard scripting language natively supported by browsers." },
             { value: "typescript", title: "TypeScript", copy: "Typically compiled to JavaScript before it runs in a browser." },
             { value: "python", title: "Python", copy: "Popular for many tasks, but not a native browser runtime language." },
             { value: "css", title: "CSS", copy: "A style sheet language used for presentation, not general application logic." }
           ],
           correctAnswers: ["javascript", "typescript"]
         },
         {
           id: "question-3",
           legend: "3. Which languages are strongly associated with data analysis and scientific computing?",
           options: [
             { value: "python", title: "Python", copy: "Widely used for notebooks, machine learning, and scientific libraries." },
             { value: "r", title: "R", copy: "Built for statistics, visualization, and analytical workflows." },
             { value: "swift", title: "Swift", copy: "Designed mainly for Apple platform app development." },
             { value: "php", title: "PHP", copy: "Commonly used for server-side web development." }
           ],
           correctAnswers: ["python", "r"]
         }
       ];

       const createChoice = (questionId, option) => `
         <div class="choice">
           <input id="${questionId}-${option.value}" type="checkbox" name="${questionId}" value="${option.value}">
           <label for="${questionId}-${option.value}">
             <span class="choice-title">${option.title}</span>
             <span class="choice-copy">${option.copy}</span>
           </label>
         </div>
       `;

       const QuizQuestion = (question) => {
         const helpId = question.helpText ? `${question.id}-help` : "";
         const errorId = `${question.id}-error`;
         const describedBy = [helpId, errorId].filter(Boolean).join(" ");

         return `
           <div class="form-field">
             <fieldset ${describedBy ? `aria-describedby="${describedBy}"` : ""} data-question="${question.id}">
               <legend>${question.legend}</legend>
               ${question.helpText ? `<p class="field-help" id="${helpId}">${question.helpText}</p>` : ""}
               <div class="choices">
                 ${question.options.map((option) => createChoice(question.id, option)).join("")}
               </div>
               <p class="field-error" id="${errorId}" hidden>Error: Select at least one answer for this question.</p>
             </fieldset>
           </div>
         `;
       };

       const App = () => `
         <section class="hero" aria-labelledby="quiz-title">
           <div class="eyebrow">Interactive learning check</div>
           <h1 id="quiz-title">Programming language essentials</h1>
           <p class="hero-copy">
             Explore three quick multiple-answer questions about popular programming languages, browser tools, and analytical stacks.
           </p>
         </section>

         <section class="quiz-card" aria-labelledby="quiz-form-title">
           <header class="quiz-card__header">
             <h2 class="quiz-card__title" id="quiz-form-title">Language knowledge quiz</h2>
             <p class="quiz-card__subtitle">Each question supports multiple selections. Choose every answer you believe is correct, then submit your quiz.</p>
           </header>

           <form id="quiz-form" novalidate>
             <div class="form-stack">
               ${quizQuestions.map(QuizQuestion).join("")}
             </div>
           </form>

           <div class="quiz-card__footer">
             <button class="button-primary" type="submit" form="quiz-form">Submit quiz</button>
             <p class="status-message" id="quiz-status" aria-live="polite">No answers submitted yet.</p>
           </div>
         </section>
       `;

       document.getElementById("app").innerHTML = App();

       const form = document.getElementById("quiz-form");
       const status = document.getElementById("quiz-status");

       const setGroupError = (questionId, hasError) => {
         const fieldset = form.querySelector(`fieldset[data-question="${questionId}"]`);
         const error = document.getElementById(`${questionId}-error`);
         const describedBy = [];
         const help = document.getElementById(`${questionId}-help`);

         if (help) {
           describedBy.push(help.id);
         }

         if (hasError) {
           describedBy.push(error.id);
           error.hidden = false;
         } else {
           error.hidden = true;
         }

         if (describedBy.length > 0) {
           fieldset.setAttribute("aria-describedby", describedBy.join(" "));
         } else {
           fieldset.removeAttribute("aria-describedby");
         }
       };

       form.addEventListener("change", (event) => {
         const { name } = event.target;

         if (!name) {
           return;
         }

         const selected = form.querySelectorAll(`input[name="${name}"]:checked`).length;
         if (selected > 0) {
           setGroupError(name, false);
         }
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         let firstInvalidInput = null;
         let score = 0;

         quizQuestions.forEach((question) => {
           const checkedValues = [...form.querySelectorAll(`input[name="${question.id}"]:checked`)].map((input) => input.value);
           const hasSelection = checkedValues.length > 0;

           setGroupError(question.id, !hasSelection);

           if (!hasSelection && !firstInvalidInput) {
             firstInvalidInput = form.querySelector(`input[name="${question.id}"]`);
           }

           const isCorrect =
             hasSelection &&
             checkedValues.length === question.correctAnswers.length &&
             checkedValues.every((value) => question.correctAnswers.includes(value));

           if (isCorrect) {
             score += 1;
           }
         });

         if (firstInvalidInput) {
           status.dataset.state = "default";
           status.textContent = "Please answer all three questions before submitting.";
           firstInvalidInput.focus();
           return;
         }

         status.dataset.state = "success";
         status.textContent = `Quiz submitted. You got ${score} out of ${quizQuestions.length} questions fully correct.`;
       });
     </script>
